Future<void> init() async {
  _isLoading = true;
  notifyListeners();
  _speedTestService = SpeedTestService();
  if (await _speedTestService.checkSimulation()) {
    _onSimulator = true;
    notifyListeners();
    return;
  } else {
    _onSimulator = false;
  }
  // _isLoading = true;
  await _speedTestService.fetchSignedUrls();
  _isLoading = false;
  notifyListeners();
  _speedTestModel = _speedTestService.speedTestModel;
  connectedToUCSDWifi();
  resetSpeedTest();
}

void connectedToUCSDWifi() async {
  isUCSDWiFi = _speedTestModel!.isUCSDWifi;
  notifyListeners();
}

Future<void> speedTest() async {
  init();
  resetSpeedTest();
  downloadSpeedTest().then((value) {
    _timer.reset();
    uploadSpeedTest().then((value) {
      final bool uploadComplete = _percentUploaded == 1.0;
      final bool downloadComplete = _percentDownloaded == 1.0;
      if (uploadComplete && downloadComplete) {
        _speedTestDone = true;
        notifyListeners();
      }
    });
  });
}

Future uploadSpeedTest() async {
  var path = (await getApplicationDocumentsDirectory()).path;
  var temp = File(path + "/temp.html");

  // if not on UCSD wifi OR the file above does not exist,
  // we should not upload the speed test results
  // instead, stop the timer and exit the function
  final bool isNotUCSDWiFi = isUCSDWiFi != true;
  final bool fileDoesNotExist = !temp.existsSync();
  if (isNotUCSDWiFi || fileDoesNotExist) {
    _timer.stop();
    notifyListeners();
    return;
  }

  var tempDownload = temp.readAsBytesSync();
  var formData = new FormData.fromMap({"file": MultipartFile.fromBytes(tempDownload, filename: "temp.html")});
  notifyListeners();

  try {
    _cancelTokenUpload = new CancelToken();
    _timer.start();
    await dio.put(
      _speedTestModel!.uploadUrl!,
      data: formData,
      onSendProgress: _progressCallbackUpload,
      cancelToken: _cancelTokenUpload,
    );
  } catch (e) {
    print(e);
  } finally {
    _timer.stop();
    notifyListeners();
  }
}

Future downloadSpeedTest() async {
  var path = (await getApplicationDocumentsDirectory()).path;
  var tempDownload = File(path + "/temp.html");
  notifyListeners();
  try {
    _cancelTokenDownload = new CancelToken();
    _timer.start();
    await dio.download(
      _speedTestModel!.downloadUrl!,
      (tempDownload.path),
      onReceiveProgress: _progressCallbackDownload,
      cancelToken: _cancelTokenDownload,
    );
  } catch (e) {
    print(e);
  } finally {
    _timer.stop();
    notifyListeners();
  }
}

_progressCallbackDownload(int bytesDownloaded, int totalBytes) {
  _secondsElapsedDownload = _timer.elapsed.inSeconds;
  double speedInBytes = (bytesDownloaded / _timer.elapsed.inSeconds);
  _speedDownload = _convertToMbps(speedInBytes);
  _percentDownloaded = bytesDownloaded / totalBytes;
  notifyListeners();
}

_progressCallbackUpload(int bytesDownloaded, int totalBytes) {
  _secondsElapsedUpload = _timer.elapsed.inSeconds;
  double speedInBytes = (bytesDownloaded / _timer.elapsed.inSeconds);
  _speedUpload = _convertToMbps(speedInBytes);
  _percentUploaded = bytesDownloaded / totalBytes;
  notifyListeners();
}

void resetSpeedTest() {
  _speedTestDone = false;
  _secondsElapsedUpload = _secondsElapsedDownload = 0;
  _timer.reset();
  _percentDownloaded = _percentUploaded = 0.0;
  _speedDownload = _speedUpload = 0.0;
  notifyListeners();
}

void cancelDownload() {
  _cancelTokenDownload!.cancel("cancelled");
  try {
    if (_timer.isRunning) {
      _timer.stop();
      _cancelTokenDownload!.cancel("cancelled");
    }
  } catch (e) {}
}

void cancelUpload() {
  _cancelTokenUpload!.cancel("cancelled");
  try {
    if (_timer.isRunning) {
      _timer.stop();
      _cancelTokenUpload!.cancel("cancelled");
    }
  } catch (e) {}
}

