class ChatCitation extends StatelessWidget {
  const ChatCitation({super.key, required this.citation});

  final ChatCitationReference citation;

  @override
  Widget build(BuildContext context) {
    return InkWell(
      onTap: () => openCitation(context, citation.url),
      borderRadius: BorderRadius.circular(16),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
        decoration: BoxDecoration(
          color: const Color(0xFFF5F7FA),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: const Color(0xFFD7DDE5)),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            SvgPicture.asset('assets/images/tgpt/document_icon.svg', width: 16, height: 14),
            const SizedBox(width: 6),
            Text(
              '[${citation.number}]',
              style: const TextStyle(
                fontFamily: 'Brix Sans',
                fontSize: 14,
                fontWeight: FontWeight.w500,
                color: Color(0xFF182B49),
              ),
            ),
          ],
        ),
      ),
    );
  }

  /// Opens [url] in an in-app [CitationWebView] so the app bar title is **CITATION**.
  ///
  /// Ignores fragment-only placeholders (e.g. `[text](#rq)` from Related Questions) and
  /// any string that is not a navigable `http`/`https` URL after resolution.
  static Future<void> openCitation(BuildContext context, String url) async {
    final String trimmed = url.trim();
    if (trimmed.isEmpty) return;
    // Related-question / UI placeholders from model markdown — not real URLs.
    if (trimmed.startsWith('#')) return;
    if (trimmed.toLowerCase().startsWith('javascript:')) return;

    String resolved = trimmed;
    if (trimmed.startsWith('//')) {
      resolved = 'https:$trimmed';
    } else {
      final Uri parsed = Uri.tryParse(trimmed) ?? Uri();
      var isMissingSchemeButHasDomain = !parsed.hasScheme && trimmed.contains('.');
      if (isMissingSchemeButHasDomain) resolved = 'https://$trimmed';
    }

    final Uri? uri = Uri.tryParse(resolved);
    var isUriNull = uri == null;
    var hasNoScheme = uri?.hasScheme == false;
    if (isUriNull || hasNoScheme) return;
    var isNotHttp = uri?.scheme != 'http';
    var isNotHttps = uri?.scheme != 'https';
    if (isNotHttp && isNotHttps) return;

    await Navigator.of(context).pushNamed(RoutePaths.TGPT_CITATION_WEB, arguments: resolved);
  }
}

