          crossAxisAlignment: CrossAxisAlignment.center,
          children: [
            Center(
              child: Text.rich(
                TextSpan(
                  text: "Unable to display STAFF ID.\n\n",
                  children: [
                    TextSpan(text: "If the problem persists, contact the "),
                    TextSpan(
