                      style: TextStyle(color: Colors.blueAccent, decoration: TextDecoration.underline),
                      recognizer: TapGestureRecognizer()
                        ..onTap = () {
                          openLink("https://blink.ucsd.edu/technology/help-desk/index.html");
                        },
                    ),
                    TextSpan(text: "."),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    ),
  );
}

                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                    ),
                    SizedBox(height: cardMargin),
                    Text(
                      "ID " + employeeIdModel.employeeId,
                      style: TextStyle(
                        fontFamily: 'Brix Sans',
                        fontWeight: FontWeight.w400,
                        fontSize: getFontSize("Employee ID " + employeeIdModel.employeeId, ""),
                      ),
                      maxLines: 1,
