/// Pop up barcode
createAlertDialog(BuildContext context, Column image, String? cardNumber, bool rotated) {
  return showDialog(
    context: context,
    builder: (context) {
      return AlertDialog(
        backgroundColor: Colors.white,
        title: Text("STAFF ID", style: TextStyle(color: Colors.black)),
        content: Container(child: checkForRotation(image, context, cardNumber, rotated)),
        actions: <Widget>[
          TextButton(
            child: Icon(Icons.close, color: Colors.black),
            onPressed: () {
              Navigator.of(context).pop();
            },
          ),
        ],
      );
    },
  );
}

Column checkForRotation(Column image, BuildContext context, String? cardNumber, bool rotated) {
  if (MediaQuery.of(context).orientation == Orientation.landscape)
    return returnBarcodeContainer(cardNumber, rotated, context);
  return image;
}

Widget buildTitle() {
  return Text(
    "STAFF ID",
    textAlign: TextAlign.left,
    style: TextStyle(fontSize: ScalingUtility.horizontalSafeBlock * 2),
  );
}

/// Determine barcode to display
returnBarcodeContainer(String? cardNumber, bool rotated, BuildContext context) {
  var barcodeWithText;

  /// Initialize sizing
  ScalingUtility().getCurrentMeasurements(context);
  if (rotated) {
    barcodeWithText = BarcodeWidget(
      barcode: Barcode.codabar(),
      data: cardNumber!,
      width: ScalingUtility.verticalSafeBlock * 45,
      height: 80,
      style: TextStyle(letterSpacing: ScalingUtility.verticalSafeBlock * 3, color: Colors.white, fontSize: 0),
    );
  } else {
    barcodeWithText = BarcodeWidget(
      barcode: Barcode.codabar(),
      data: cardNumber!,
      width: ScalingUtility.horizontalSafeBlock * 50,
      height: ScalingUtility.verticalSafeBlock * 4.45,
      style: TextStyle(letterSpacing: ScalingUtility.horizontalSafeBlock * 1.5, fontSize: 0, color: Colors.white),
    );
  }

  if (rotated) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.center,
      children: <Widget>[
        RotatedBox(
          quarterTurns: 1,
          child: Row(
            children: <Widget>[
              Padding(padding: EdgeInsets.all(ScalingUtility.verticalSafeBlock * 7.5)),
              Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: <Widget>[
                  Container(child: barcodeWithText, color: Colors.white),
                  Text(
                    cardNumber,
                    style: TextStyle(
                      color: Colors.black,
                      fontSize: fontSizeForTablet(),
                      letterSpacing: letterSpacingForTablet(),
                    ),
                  ),
                ],
              ),
            ],
          ),
        ),
      ],
    );
  } else {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: <Widget>[
        Padding(
          padding: const EdgeInsets.fromLTRB(0, 15, 0, 5),
          child: Text(
            "tap for easier scanning",
            textAlign: TextAlign.center,
            style: linkTextLight.copyWith(fontSize: 18.0),
          ),
        ),
        Container(padding: EdgeInsets.fromLTRB(0, 0, 10, 0), color: Colors.white, child: barcodeWithText),
      ],
    );
  }
}

double letterSpacingForTablet() {
  final bool isLandscape = MediaQuery.of(context).orientation == Orientation.landscape;
  if (isLandscape) return ScalingUtility.horizontalSafeBlock * 1;
  return ScalingUtility.horizontalSafeBlock * 2;
}

double fontSizeForTablet() {
  final bool isLandscape = MediaQuery.of(context).orientation == Orientation.landscape;
  if (isLandscape) return ScalingUtility.horizontalSafeBlock * 2;
  return ScalingUtility.horizontalSafeBlock * 4;
}

returnBarcodeContainerTablet(String? cardNumber, bool rotated, BuildContext context) {
  var barcodeWithText;
  SizeConfig().init(context);
  if (rotated) {
    barcodeWithText = BarcodeWidget(
      barcode: Barcode.codabar(),
      data: cardNumber!,
      width: SizeConfig.safeBlockVertical * 60,
      height: 80,
      style: TextStyle(letterSpacing: SizeConfig.safeBlockVertical * 3, fontSize: 0, color: Colors.white),
    );
  } else {
    barcodeWithText = BarcodeWidget(
      barcode: Barcode.codabar(),
      data: cardNumber!,
      width: SizeConfig.safeBlockHorizontal * 20,
      height: 40,
      style: TextStyle(letterSpacing: SizeConfig.safeBlockHorizontal * 1.5, fontSize: 0, color: Colors.white),
    );
  }

  if (rotated) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.center,
      children: <Widget>[
        Padding(padding: EdgeInsets.all(25)),
        RotatedBox(
          quarterTurns: 1,
          child: Row(
            children: <Widget>[
              Padding(padding: EdgeInsets.all(SizeConfig.safeBlockVertical * 7.5)),
              Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: <Widget>[
                  Container(child: barcodeWithText, color: Colors.white),
                  Text(
                    cardNumber,
                    style: TextStyle(
                      color: Colors.black,
                      fontSize: getRotatedPopUpFontSize(),
                      letterSpacing: letterSpacing(),
                    ),
                  ),
                ],
              ),
            ],
          ),
        ),
      ],
    );
  } else {
    return Column(
      children: <Widget>[
        Text(
          "(tap for easier scanning)",
          textAlign: TextAlign.left,
          style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16.0, color: decideColor(Theme.of(context))),
        ),
        Container(padding: addBorder(Theme.of(context)), color: Colors.white, child: barcodeWithText),
        Text(
          cardNumber,
          style: TextStyle(
            fontSize: ScalingUtility.horizontalSafeBlock * 1.25,
            letterSpacing: ScalingUtility.horizontalSafeBlock * .5,
          ),
        ),
      ],
    );
  }
}

double letterSpacing() => MediaQuery.of(context).orientation == Orientation.landscape
    ? SizeConfig.safeBlockHorizontal * 1
    : SizeConfig.safeBlockHorizontal * 3;

double getRotatedPopUpFontSize() => MediaQuery.of(context).orientation == Orientation.landscape
    ? SizeConfig.safeBlockHorizontal * 2
    : SizeConfig.safeBlockHorizontal * 4;

/// Determine the font size for user's textFields
double getFontSize(String input, String textField) {
  /// Base font size
  double base = ScalingUtility.horizontalSafeBlock * 3.5;

  /// If threshold is passed, shrink text
  if (input.length >= 21) return (base - (0.175 * (input.length - 18)));

  /// The name should be large than subheadings
  if (textField == "name") {
    base = ScalingUtility.horizontalSafeBlock * 6;
    return base;
  }

  return base;
}

double tabletFontSize(String input, String textField) {
  /// Base font size
  double base = letterSpacingForTablet();

  /// If threshold is passed, shrink text
  // if (input.length >= 21) {
  //   return (base - (0.1725 * (input.length - 18)));
  // }

  /// The name should be large than subheadings
  textField == "name"
      ? base = ScalingUtility.horizontalSafeBlock * 1.75
      : base = ScalingUtility.horizontalSafeBlock * 1.25;

  return base;
}

  /// Determine the padding for a border around barcode
  EdgeInsets addBorder(ThemeData currentTheme) =>
      currentTheme.brightness == Brightness.dark ? EdgeInsets.all(5) : EdgeInsets.all(0);

  /// Determine the padding for the text to realign
  double realignText(ThemeData currentTheme) => currentTheme.brightness == Brightness.dark ? 7 : 0;

  /// Determine the  color of hint above the barcode
  Color decideColor(ThemeData currentTheme) =>
      currentTheme.brightness == Brightness.dark ? Colors.white : Colors.black45;
}

// Image Scaling
class ScalingUtility {
  late MediaQueryData _queryData;
  static late double horizontalSafeBlock;
  static late double verticalSafeBlock;

  void getCurrentMeasurements(BuildContext context) {
    /// Find screen size
    _queryData = MediaQuery.of(context);

    /// Calculate blocks accounting for notches and home bar
    horizontalSafeBlock = (_queryData.size.width - (_queryData.padding.left + _queryData.padding.right)) / 100;
    verticalSafeBlock = (_queryData.size.height - (_queryData.padding.top + _queryData.padding.bottom)) / 100;
  }
}

class SizeConfig {
  static late MediaQueryData _mediaQueryData;
  static late double screenWidth;
  static late double screenHeight;
  static double? blockSizeHorizontal;
  static double? blockSizeVertical;
  static late double _safeAreaHorizontal;
  static late double _safeAreaVertical;
  static late double safeBlockHorizontal;
  static late double safeBlockVertical;

  void init(BuildContext context) {
    _mediaQueryData = MediaQuery.of(context);
    screenWidth = _mediaQueryData.size.width;
    screenHeight = _mediaQueryData.size.height;
    blockSizeHorizontal = screenWidth / 100;
    blockSizeVertical = screenHeight / 100;

    _safeAreaHorizontal = _mediaQueryData.padding.left + _mediaQueryData.padding.right;
    _safeAreaVertical = _mediaQueryData.padding.top + _mediaQueryData.padding.bottom;
    safeBlockHorizontal = (screenWidth - _safeAreaHorizontal) / 100;
    safeBlockVertical = (screenHeight - _safeAreaVertical) / 100;
  }
}

