        } else {
          _mapController!.animateCamera(
            CameraUpdate.newLatLng(
              LatLng(
                Provider.of<MapsDataProvider>(context, listen: false).coordinates!.lat!,
                Provider.of<MapsDataProvider>(context, listen: false).coordinates!.lon!,
              ),
            ),
          );
        }
      },
    );
  }
}

