class NotificationsFilterView extends StatelessWidget {
  @override
  Widget build(BuildContext context) => ContainerView(child: buildSettingsList(context, getTopics(context)));

  Widget buildSettingsList(BuildContext context, List<String?>? topicsData) {
    return (topicsData ?? []).isNotEmpty
        ? Padding(
            padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
            child: ListView(
              children: ListTile.divideTiles(
                context: context,
                tiles: createList(context, topicsData as List<String?>),
                color: Theme.of(context).brightness == Brightness.dark
                    ? listTileDividerColorDark
                    : listTileDividerColorLight,
              ).toList(),
            ),
          )
        : Center(child: CircularProgressIndicator(color: Theme.of(context).colorScheme.secondary));
  }

List<Widget> createList(BuildContext context, List<String?> topicsAvailable) {
  List<Widget> list = [];
  for (String? topic in topicsAvailable) {
    list.add(
      Padding(
        padding: const EdgeInsets.symmetric(vertical: 8.0),
        child: ListTile(
          horizontalTitleGap: 0,
          contentPadding: EdgeInsets.all(0),
          visualDensity: VisualDensity.compact,
          key: Key(topic!),
          leading: Icon(chooseIcons(topic), color: Theme.of(context).iconTheme.color, size: 30),
          title: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 4.0),
            child: Text(getTopicName(context, topic)!, style: Theme.of(context).textTheme.labelMedium),
          ),
          trailing: Transform.scale(
            scale: 0.9,
            child: Switch.adaptive(
              value: Provider.of<UserDataProvider>(context).subscribedTopics?.contains(topic) ?? false,
              onChanged: (_) {
                Provider.of<UserDataProvider>(context, listen: false).toggleNotifications(topic);
              },
              thumbColor: WidgetStateProperty.resolveWith((states) {
                final bool isSelected = states.contains(WidgetState.selected);
                if (isSelected) return Colors.white;
                return null;
              }),
              activeTrackColor: toggleActiveColor,
            ),
          ),
        ),
      ),
    );
  }
  return list;
}

static IconData chooseIcons(String messageType) {
  switch (messageType) {
    case "studentAnnouncements":
    case "testStudentAnnouncements":
      return Icons.school_outlined;
    case "freeFood":
    case "testFreeFood":
      return Icons.restaurant_outlined;
    case "campusAnnouncements":
    case "testCampusAnnouncements":
      return Icons.campaign_outlined;
    case "DM":
      return Icons.info_outline;
    default:
      return Icons.info_outline;
  }
}

  List<String?> getTopics(BuildContext context) {
    UserDataProvider _userDataProvider = Provider.of<UserDataProvider>(context);
    PushNotificationDataProvider _pushNotificationDataProvider = Provider.of<PushNotificationDataProvider>(context);
    if (_userDataProvider.userProfileModel.classifications?.student ?? false) {
      return _pushNotificationDataProvider.publicTopics() + _pushNotificationDataProvider.studentTopics();
    } else {
      final bool isStaff = _userDataProvider.userProfileModel.classifications?.staff ?? false;
      if (isStaff) {
        return _pushNotificationDataProvider.publicTopics() + _pushNotificationDataProvider.staffTopics();
      } else {
        return _pushNotificationDataProvider.publicTopics();
      }
    }
  }

  String? getTopicName(BuildContext context, String topicId) =>
      Provider.of<PushNotificationDataProvider>(context).getTopicName(topicId);
}

import 'package:campus_mobile_experimental/core/providers/notifications_freefood.dart';
import 'package:flutter/material.dart';
import 'package:provider/provider.dart';

class FreeFoodNotification extends StatefulWidget {
  /// required parameters
  final String? messageId;

  const FreeFoodNotification({Key? key, required this.messageId}) : super(key: key);

  @override
  _CheckBoxButtonState createState() => _CheckBoxButtonState(messageId);
}

class _CheckBoxButtonState extends State<FreeFoodNotification> {
  _CheckBoxButtonState(messageId) {
    this.messageId = messageId;
  }

  /// STATES
  String? messageId;
  var _isLoading = false;
  var _isGoing = false;
  var _buttonColor = Colors.white;
  var _borderColor = Color(0xFF034161);
  var _textColor = Color(0xFF034161);

  /// PROVIDERS
  late FreeFoodDataProvider _freeFoodDataProvider;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _freeFoodDataProvider = Provider.of<FreeFoodDataProvider>(context);
    _isLoading = _freeFoodDataProvider.isLoading(messageId);
    _isGoing = _freeFoodDataProvider.registeredEvents!.contains(messageId);
    if (_isGoing) {
      _buttonColor = Colors.green;
      _borderColor = Colors.green;
      _textColor = Colors.white;
    } else {
      _buttonColor = Colors.white;
      _borderColor = Color(0xFF034161);
      _textColor = Color(0xFF034161);
    }
  }

@override
Widget build(BuildContext context) {
  var isOverCount = _freeFoodDataProvider.isOverCount(messageId!);
  // print('messageId "' + messageId + '" isOverCount: ' + isOverCount.toString());
  var currCount = _freeFoodDataProvider.count(messageId!);
  var countText = currCount == 1 ? '$currCount student is going' : '$currCount students are going';

  return Container(
    margin: EdgeInsets.only(top: 8.0),
    child: Row(
      children: <Widget>[
        Expanded(
          child: Container(
            height: 40,
            child: AnimatedCrossFade(
              duration: Duration(milliseconds: 300),
              crossFadeState: isOverCount ? CrossFadeState.showFirst : CrossFadeState.showSecond,
              firstChild: Column(
                children: <Widget>[
                  Text(countText, style: TextStyle(fontSize: 10, color: Colors.red)),
                  Container(
                    margin: EdgeInsets.only(top: 2.0),
                    child: Row(
                      children: <Widget>[
                        Icon(Icons.report, color: Colors.grey, size: 15),
                        Expanded(child: Text("There may not be enough food", style: TextStyle(fontSize: 12))),
                      ],
                    ),
                  ),
                ],
                crossAxisAlignment: CrossAxisAlignment.start,
              ),
              secondChild: Align(
                alignment: Alignment.topLeft,
                child: Text(countText, style: TextStyle(fontSize: 12, color: Colors.green)),
              ),
            ),
          ),
        ),
        _checkBoxButton(),
      ],
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
    ),
  );
}

Widget _checkBoxButton() {
  return Container(
    height: 23,
    width: 100,
    decoration: BoxDecoration(
      border: Border.all(width: 1.0, color: _borderColor),
      borderRadius: BorderRadius.all(Radius.circular(2.0)),
    ),
    margin: EdgeInsets.only(right: 10.0),
    child: _isLoading
        ? Center(
            child: Container(
              height: 12,
              width: 12,
              child: CircularProgressIndicator(color: Theme.of(context).colorScheme.secondary, strokeWidth: 1.5),
            ),
          )
        : Material(
            color: _buttonColor,
            child: InkWell(
              onTap: () {
                _toggleGoing();
              },
              child: Center(
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                  children: <Widget>[
                    SizedBox(
                      height: 10.0,
                      width: 8.0,
                      child: Transform.scale(
                        scale: 0.5,
                        child: Checkbox(
                          checkColor: Colors.green,
                          activeColor: Colors.white,
                          value: _isGoing,
                          onChanged: (bool? val) {
                            _toggleGoing();
                          },
                        ),
                      ),
                    ),
                    Text("I'm Going!", style: TextStyle(color: _textColor, fontSize: 12)),
                  ],
                ),
              ),
            ),
          ),
  );
}

  void _toggleGoing() {
    setState(() {
      if (_isGoing) {
        _buttonColor = Colors.white;
        _borderColor = Color(0xFF034161);
        _textColor = Color(0xFF034161);
        _freeFoodDataProvider.decrementCount(messageId!);
      } else {
        _buttonColor = Colors.green;
        _borderColor = Colors.green;
        _textColor = Colors.white;
        _freeFoodDataProvider.incrementCount(messageId!);
      }
      _isGoing = !_isGoing;
    });
  }
}

