var hideListView = false;

class NotificationsListView extends StatefulWidget {
  @override
  State<NotificationsListView> createState() => _NotificationsListViewState();
}

class _NotificationsListViewState extends State<NotificationsListView> {
  @override
  void initState() {
    super.initState();
    hideListView = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      Provider.of<MessagesDataProvider>(
        context,
        listen: false,
      ).notificationScrollController.jumpTo(getNotificationsScrollOffset());
      setState(() {
        hideListView = false;
      });
    });
  }

  @override
  Widget build(BuildContext context) {
    initUniLinks(context);
    return Offstage(
      offstage: hideListView,
      child: RefreshIndicator(
        child: buildListView(context),
        onRefresh: () {
          return Provider.of<MessagesDataProvider>(context, listen: false).fetchMessages(true);
        },
        color: Theme.of(context).colorScheme.secondary,
      ),
    );
  }

Widget buildListView(BuildContext context) {
  final messagesProvider = Provider.of<MessagesDataProvider>(context);
  final messages = messagesProvider.messages;

  // TODO: fix this logic up - December 2025
  Widget Function(BuildContext context, int index)? itemBuilder;
  var itemCount = 0;
  if (messages.isEmpty) {
    if (messagesProvider.error == null) {
      if (messagesProvider.isLoading) {
        // empty notifications view until they load in
      } else {
        itemBuilder = (BuildContext context, int index) => _buildNoMessagesText();
        itemCount = 1;
      }
    } else {
      itemBuilder = (BuildContext context, int index) => _buildErrorText();
      itemCount = 1;
    }
  }
  if (itemCount == 0) {
    itemBuilder = (BuildContext context, int index) => _buildMessage(context, messages[index]);
    itemCount = messages.length;
  }
  return Padding(
    padding: const EdgeInsets.symmetric(horizontal: 16.0),
