              context,
            ).textTheme.bodySmall?.copyWith(fontSize: 16, height: 1.41, fontWeight: FontWeight.w400),
          ),
          freefoodProvider.isFreeFood(data.messageId) ? FreeFoodNotification(messageId: data.messageId) : Container(),
        ],
      ),
    ),
    trailing: Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        Padding(
          padding: const EdgeInsets.only(top: 6.0),
          child: Text(
            _readTimestamp(data.timestamp),
            style: Theme.of(
              context,
            ).textTheme.bodySmall?.copyWith(fontSize: 12, height: 1.41, fontWeight: FontWeight.w700),
          ),
        ),
      ],
    ),
  );
}

  static String _readTimestamp(int timestamp) {
    var now = new DateTime.now();
    var date = new DateTime.fromMillisecondsSinceEpoch(timestamp);
    var diff = now.difference(date);
    var time = '';

    if (diff.inSeconds < 60) {
      time = 'JUST NOW';
    } else if (diff.inMinutes < 60) {
      time = '${diff.inMinutes} ${diff.inMinutes == 1 ? 'MIN' : 'MINS'}';
    } else if (diff.inHours < 24) {
      time = '${diff.inHours} ${diff.inHours == 1 ? 'HR' : 'HRS'}';
    } else if (diff.inDays < 7) {
      time = '${diff.inDays} D';
    } else if (diff.inDays < 365) {
      time = '${(diff.inDays / 7).floor()} W';
    } else {
      time = '${(diff.inDays / 365).floor()} Y';
    }
    return time;
  }
}

