            ),
            trailing: IconButton(
              icon: Icon(Icons.close),
              tooltip: 'Remove ${model.name}',
              onPressed: () async {
                await _shuttleDataProvider.removeStop(model.id);
              },
            ),
          ),
        ),
      );
    }
  }
  return list;
}

